private static DataTable BuildEmptyBedTable(DataTable dtbBeds)
{
    if (dtbBeds == null || dtbBeds.Rows.Count == 0)
    {
        return null;
    }

    DataTable dtbResult = null;
    foreach (DataRow drwBed in dtbBeds.Rows)
    {
        if (!IsEmptySelectableBed(drwBed))
        {
            continue;
        }

        if (dtbResult == null)
        {
            dtbResult = dtbBeds.Clone();
        }

        dtbResult.ImportRow(drwBed);
    }

    return dtbResult;
}

private DataTable BuildBedTableForArea(string areaId)
