    DataTable dtbResult = null;
    DataTable dtbDorms = dataAccess.GetDormListForRegister(areaId, WebGlobal.StudentID);
    if (dtbDorms == null || dtbDorms.Rows.Count == 0)
    {
        return dtbResult;
    }

    foreach (DataRow drwDorm in dtbDorms.Rows)
    {
        string strDormId = drwDorm[SIM_Dorm.C_DormID].ToString();
        DataTable dtbBeds = dataAccess.GetBedListForRegister(strDormId, WebGlobal.StudentID);
