private DataTable BuildRoomSummaryTable(DataTable dtbBeds)
{
    DataTable dtbRooms = new DataTable();
    dtbRooms.Columns.Add("DormID", typeof(string));
    dtbRooms.Columns.Add("DormName", typeof(string));
    dtbRooms.Columns.Add("BedCount", typeof(int));
    dtbRooms.Columns.Add("Price", typeof(decimal));

    if (dtbBeds == null || dtbBeds.Rows.Count == 0)
    {
        return dtbRooms;
    }

    System.Collections.Generic.Dictionary<string, int> dicCount =
        new System.Collections.Generic.Dictionary<string, int>();
    System.Collections.Generic.Dictionary<string, string> dicName =
        new System.Collections.Generic.Dictionary<string, string>();
    System.Collections.Generic.Dictionary<string, object> dicPrice =
        new System.Collections.Generic.Dictionary<string, object>();
    bool bolHasPrice = dtbBeds.Columns.Contains(SIM_Dorm.C_Price);

    foreach (DataRow drw in dtbBeds.Rows)
    {
        string strDormId = drw[SIM_Dorm.C_DormID].ToString();
        if (!dicCount.ContainsKey(strDormId))
        {
            dicCount[strDormId] = 0;
            dicName[strDormId] = drw["DormName"].ToString();
            if (bolHasPrice && !Convert.IsDBNull(drw[SIM_Dorm.C_Price]))
            {
                dicPrice[strDormId] = drw[SIM_Dorm.C_Price];
            }
        }

        dicCount[strDormId] = dicCount[strDormId] + 1;
    }

    foreach (System.Collections.Generic.KeyValuePair<string, int> kvp in dicCount)
    {
        DataRow drwNew = dtbRooms.NewRow();
        drwNew["DormID"] = kvp.Key;
        drwNew["DormName"] = dicName[kvp.Key];
        drwNew["BedCount"] = kvp.Value;
        if (dicPrice.ContainsKey(kvp.Key))
        {
            drwNew["Price"] = dicPrice[kvp.Key];
        }
        else
        {
            drwNew["Price"] = DBNull.Value;
        }
        dtbRooms.Rows.Add(drwNew);
    }

    DataView dvRoom = dtbRooms.DefaultView;
    dvRoom.Sort = "DormName";
    return dvRoom.ToTable();
}

