private DataTable BuildRoomSummaryTable()
{
    DataTable dtbRooms = new DataTable();
    dtbRooms.Columns.Add("DormID", typeof(string));
    dtbRooms.Columns.Add("DormName", typeof(string));
    dtbRooms.Columns.Add("TotalBedCount", typeof(int));
    dtbRooms.Columns.Add("EmptyBedCount", typeof(int));
    dtbRooms.Columns.Add("Price", typeof(decimal));

    if (dtbBedsInArea == null || dtbBedsInArea.Rows.Count == 0)
    {
        return dtbRooms;
    }

    System.Collections.Generic.Dictionary<string, RoomSummary> dicRooms =
        new System.Collections.Generic.Dictionary<string, RoomSummary>(StringComparer.OrdinalIgnoreCase);
    bool bolHasPrice = dtbBedsInArea.Columns.Contains(SIM_Dorm.C_Price);
    string strBedStatusFilter = ddlBedStatus != null ? ddlBedStatus.SelectedValue : string.Empty;
    string strRoomSearch = txtRoomSearch != null ? txtRoomSearch.Text.Trim() : string.Empty;

    foreach (DataRow drw in dtbBedsInArea.Rows)
    {
        string strDormId = drw[SIM_Dorm.C_DormID].ToString();
        string strDormName = drw["DormName"].ToString();
        RoomSummary summary;
        if (!dicRooms.TryGetValue(strDormId, out summary))
        {
            summary = new RoomSummary();
            summary.DormId = strDormId;
            summary.DormName = strDormName;
            if (bolHasPrice && !Convert.IsDBNull(drw[SIM_Dorm.C_Price]))
            {
                summary.Price = drw[SIM_Dorm.C_Price];
            }
            dicRooms[strDormId] = summary;
        }

        summary.TotalBedCount++;
        int intStatus = Convert.ToInt32(drw["BedStatus"]);
        if (intStatus == DormRegisterConst.BedStatusEmpty)
        {
            summary.EmptyBedCount++;
        }

        if (MatchesBedStatusFilter(intStatus, strBedStatusFilter))
        {
            summary.MatchingBedCount++;
        }
    }

    foreach (RoomSummary summary in dicRooms.Values)
    {
        if (!string.IsNullOrEmpty(ddlDorm.SelectedValue)
            && !string.Equals(summary.DormId, ddlDorm.SelectedValue, StringComparison.OrdinalIgnoreCase))
        {
            continue;
        }

        if (!string.IsNullOrEmpty(strRoomSearch)
            && summary.DormName.IndexOf(strRoomSearch, StringComparison.OrdinalIgnoreCase) < 0)
        {
            continue;
        }

        if (!string.IsNullOrEmpty(strBedStatusFilter) && summary.MatchingBedCount <= 0)
        {
            continue;
        }

        DataRow drwNew = dtbRooms.NewRow();
        drwNew["DormID"] = summary.DormId;
        drwNew["DormName"] = summary.DormName;
        drwNew["TotalBedCount"] = summary.TotalBedCount;
        drwNew["EmptyBedCount"] = summary.EmptyBedCount;
        if (summary.Price != null)
        {
            drwNew["Price"] = summary.Price;
        }
        else
        {
            drwNew["Price"] = DBNull.Value;
        }
        dtbRooms.Rows.Add(drwNew);
    }

    DataView dvRoom = dtbRooms.DefaultView;
    dvRoom.Sort = "DormName";
    return dvRoom.ToTable();
}

private static bool MatchesBedStatusFilter(int bedStatus, string filterValue)
{
    if (string.IsNullOrEmpty(filterValue))
    {
        return true;
    }

    int intFilter;
    if (!int.TryParse(filterValue, NumberStyles.Integer, CultureInfo.InvariantCulture, out intFilter))
    {
        return true;
    }

    return bedStatus == intFilter;
}

private sealed class RoomSummary
{
    public string DormId;
    public string DormName;
    public int TotalBedCount;
    public int EmptyBedCount;
    public int MatchingBedCount;
    public object Price;
}

