        protected string FormatRoomVacancy(object emptyCount, object totalCount)
        {
            int intEmpty;
            int intTotal;
            if (!TryToInt(emptyCount, out intEmpty) || !TryToInt(totalCount, out intTotal))
            {
                return string.Empty;
            }

            return String.Format(CultureInfo.InvariantCulture, "{0}/{1} trống", intEmpty, intTotal);
        }

        protected string GetRoomVacancyCss(object emptyCount, object totalCount)
        {
            int intEmpty;
            int intTotal;
            if (!TryToInt(emptyCount, out intEmpty) || !TryToInt(totalCount, out intTotal))
            {
                return string.Empty;
            }

            if (intEmpty <= 0)
            {
                return "is-full";
            }

            if (intEmpty >= intTotal)
            {
                return "is-all-empty";
            }

            return "is-partial";
        }

        private static bool TryToInt(object value, out int result)
        {
            result = 0;
            if (value == null || value == DBNull.Value)
            {
                return false;
            }

            if (value is int)
            {
                result = (int)value;
                return true;
            }

            return int.TryParse(value.ToString(), NumberStyles.Integer, CultureInfo.InvariantCulture, out result);
        }
    }
}

