private bool IsBedStillSelectable(string dormBedId, out string userMessage)
{
    userMessage = "Giường này vừa được sinh viên khác đăng ký. Vui lòng chọn giường khác.";
    if (string.IsNullOrEmpty(ddlArea.SelectedValue))
    {
        return false;
    }

    DataTable dtbFresh = LoadAllBedsForArea(ddlArea.SelectedValue);
    if (dtbFresh == null)
    {
        return false;
    }

    foreach (DataRow drw in dtbFresh.Rows)
    {
        if (!string.Equals(drw["DormBedID"].ToString(), dormBedId, StringComparison.OrdinalIgnoreCase))
        {
            continue;
        }

        int intStatus = Convert.ToInt32(drw["BedStatus"]);
        int intSelectable = Convert.ToInt32(drw["IsSelectable"]);
        if (intStatus == DormRegisterConst.BedStatusEmpty && intSelectable == 1)
        {
            return true;
        }

        if (intStatus == DormRegisterConst.BedStatusHeld)
        {
            userMessage = "Giường này vừa được sinh viên khác giữ chỗ. Vui lòng chọn giường khác.";
        }

        return false;
    }

    userMessage = "Giường không còn khả dụng. Vui lòng chọn giường khác.";
    return false;
}

private static string MapBedConflictMessage(string sourceMessage)
{
    if (string.IsNullOrEmpty(sourceMessage))
    {
        return sourceMessage;
    }

    if (sourceMessage.IndexOf("Giường vừa", StringComparison.OrdinalIgnoreCase) >= 0
        || sourceMessage.IndexOf("giữ chỗ", StringComparison.OrdinalIgnoreCase) >= 0)
    {
        return "Giường này vừa được sinh viên khác đăng ký. Vui lòng chọn giường khác.";
    }

    return sourceMessage;
}

private static bool IsBedConflictMessage(string message)
{
    if (string.IsNullOrEmpty(message))
    {
        return false;
    }

    return message.IndexOf("vừa được sinh viên khác đăng ký", StringComparison.OrdinalIgnoreCase) >= 0
        || message.IndexOf("Giường vừa", StringComparison.OrdinalIgnoreCase) >= 0;
}

