protected string FormatRoomTitle(object dormName)
{
    if (dormName == null || dormName == DBNull.Value)
    {
        return string.Empty;
    }

    string strName = dormName.ToString().Trim();
    if (strName.Length == 0)
    {
        return string.Empty;
    }

    if (strName.StartsWith("Phòng", StringComparison.OrdinalIgnoreCase))
    {
        return strName;
    }

    return String.Format(CultureInfo.InvariantCulture, "Phòng {0}", strName);
}

protected string GetRoomCardCss(object emptyCount)
{
