    font-size: 0.75rem;
    font-weight: 600;
    color: var(--dorm-reg-green);
}

.dorm-register-room-beds-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.45rem;
}

.dorm-register-bed-tile {
    position: relative;
    border: 1px solid #e2e8f0;
    border-radius: 0.55rem;
    padding: 0.45rem 0.4rem 0.5rem;
    text-align: center;
    min-height: 4.5rem;
    background: #f8fafc;
}

.dorm-register-bed-tile-icon {
    display: block;
    font-size: 1.15rem;
    margin-bottom: 0.15rem;
    color: #94a3b8;
}

.dorm-register-bed-tile.is-empty.is-selectable {
