}

.dorm-register-bed-tile.is-empty.is-selectable .dorm-register-bed-tile-icon {
    color: var(--dorm-reg-green);
}

.dorm-register-bed-tile.is-empty.is-selectable .dorm-register-bed-status-inline {
    color: var(--dorm-reg-green);
}

.dorm-register-bed-tile.is-empty.is-selectable:hover {
