    border-color: var(--dorm-reg-green);
}

.dorm-register-bed-tile.is-empty.is-selectable.is-picked {
    border-color: var(--dorm-bed-accent);
    box-shadow: 0 0 0 2px rgba(30, 77, 140, 0.15);
}

.dorm-register-bed-tile.is-occupied {
    background: #f1f5f9;
    border-color: #e2e8f0;
    opacity: 0.92;
}

.dorm-register-bed-tile.is-occupied .dorm-register-bed-status-inline {
    color: #64748b;
}

.dorm-register-bed-tile.is-held {
    background: #fffbeb;
    border-color: #fde68a;
}

.dorm-register-bed-tile.is-held .dorm-register-bed-status-inline {
