}

.dorm-register-bed-tile .dorm-register-bed-name {
    display: block;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #334155;
    line-height: 1.2;
}

.dorm-register-bed-tile .dorm-register-bed-status-inline {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.625rem;
    font-weight: 600;
