    right: 0.3rem;
    font-size: 0.85rem;
    color: var(--dorm-bed-accent);
}

.dorm-register-bed-tile.is-picked .dorm-register-bed-pick-icon {
    display: block;
}

@media (max-width: 991.98px) {
    .dorm-register-steps-v2 {
        grid-template-columns: 1fr;
    }

    .dorm-register-stats-row {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 575.98px) {
    .dorm-register-stats-row {
        grid-template-columns: 1fr;
    }

    .dorm-register-room-grid {
        grid-template-columns: 1fr;
    }
}

