function dormRegisterCleanupModalUi() {
    var modalEl = document.getElementById('dormRegisterConfirmModal');
    if (modalEl) {
        if (window.bootstrap && bootstrap.Modal) {
            var inst = bootstrap.Modal.getInstance(modalEl);
            if (inst) {
                inst.hide();
            }
        }
        modalEl.classList.remove('show');
        modalEl.setAttribute('aria-hidden', 'true');
        modalEl.style.display = 'none';
    }
    var visibleModals = document.querySelectorAll('.modal.show');
    if (visibleModals.length > 0) {
        var backs = document.querySelectorAll('.modal-backdrop');
        if (backs.length > 1) {
            for (var j = backs.length - 1; j >= 1; j--) {
                if (backs[j].parentNode) {
                    backs[j].parentNode.removeChild(backs[j]);
                }
            }
        }
        return;
    }
    var backsAll = document.querySelectorAll('.modal-backdrop');
    for (var i = 0; i < backsAll.length; i++) {
        if (backsAll[i].parentNode) {
            backsAll[i].parentNode.removeChild(backsAll[i]);
        }
    }
    document.body.classList.remove('modal-open');
    if (document.body.style.removeProperty) {
        document.body.style.removeProperty('overflow');
        document.body.style.removeProperty('padding-right');
    } else {
        document.body.style.overflow = '';
        document.body.style.paddingRight = '';
    }
}
if (window.Sys && Sys.WebForms && Sys.WebForms.PageRequestManager) {
    Sys.WebForms.PageRequestManager.getInstance().add_endRequest(function () {
        dormRegisterCleanupModalUi();
    });
}
