function dormRegisterCloseFilterPanel() {
    var filterCard = document.getElementById('dormRegisterFilterCard');
    var fab = document.getElementById('dormRegisterFilterFab');
    var backdrop = document.getElementById('dormRegisterFilterBackdrop');
    if (filterCard) {
        filterCard.classList.remove('is-fab-open');
    }
    if (fab) {
        fab.classList.remove('is-active');
        fab.setAttribute('aria-expanded', 'false');
    }
    if (backdrop) {
        backdrop.classList.remove('is-visible');
    }
    document.body.classList.remove('dorm-register-filter-panel-open');
}
function dormRegisterOpenFilterPanel() {
    var filterCard = document.getElementById('dormRegisterFilterCard');
    var fab = document.getElementById('dormRegisterFilterFab');
    var backdrop = document.getElementById('dormRegisterFilterBackdrop');
    if (!filterCard || !fab) {
        return;
    }
    filterCard.classList.add('is-fab-open');
    fab.classList.add('is-active');
    fab.setAttribute('aria-expanded', 'true');
    if (backdrop) {
        backdrop.classList.add('is-visible');
    }
    document.body.classList.add('dorm-register-filter-panel-open');
}
function dormRegisterFilterStickyTick() {
    var filterCard = document.getElementById('dormRegisterFilterCard');
    var fab = document.getElementById('dormRegisterFilterFab');
    var wrap = document.getElementById('dormRegisterFilterWrap');
    if (!filterCard || !fab) {
        return;
    }
    if (window.innerWidth > 575) {
        fab.classList.remove('is-visible');
        if (wrap) {
            wrap.classList.remove('is-filter-passed');
        }
        dormRegisterCloseFilterPanel();
        return;
    }
    var rect = filterCard.getBoundingClientRect();
    var passed = rect.bottom < 8;
    if (passed) {
        fab.classList.add('is-visible');
        if (wrap) {
            wrap.classList.add('is-filter-passed');
        }
    } else {
        fab.classList.remove('is-visible');
        if (wrap) {
            wrap.classList.remove('is-filter-passed');
        }
        if (!filterCard.classList.contains('is-fab-open')) {
            dormRegisterCloseFilterPanel();
        }
    }
}
function dormRegisterInitFilterSticky() {
    var fab = document.getElementById('dormRegisterFilterFab');
    var backdrop = document.getElementById('dormRegisterFilterBackdrop');
    if (!fab || fab.getAttribute('data-dorm-filter-init') === '1') {
        dormRegisterFilterStickyTick();
        return;
    }
    fab.setAttribute('data-dorm-filter-init', '1');
    fab.onclick = function () {
        var filterCard = document.getElementById('dormRegisterFilterCard');
        if (!filterCard) {
            return;
        }
        if (filterCard.classList.contains('is-fab-open')) {
            dormRegisterCloseFilterPanel();
        } else {
            dormRegisterOpenFilterPanel();
        }
    };
    if (backdrop) {
        backdrop.onclick = function () {
            dormRegisterCloseFilterPanel();
        };
    }
    window.addEventListener('scroll', dormRegisterFilterStickyTick, false);
    window.addEventListener('resize', dormRegisterFilterStickyTick, false);
    dormRegisterFilterStickyTick();
}
dormRegisterMoveConfirmModalToBody();
dormRegisterInitFilterSticky();
if (window.Sys && Sys.WebForms && Sys.WebForms.PageRequestManager) {
    Sys.WebForms.PageRequestManager.getInstance().add_endRequest(function () {
        dormRegisterMoveConfirmModalToBody();
        dormRegisterCleanupModalUi();
        dormRegisterCloseFilterPanel();
        dormRegisterInitFilterSticky();
    });
}

